import numpy as np

def solve(pairs, width, height):
    """Solve ARC puzzle"""

    # Count points per row/col
    row_counts = {}
    col_counts = {}
    for r, c in pairs:
        row_counts[r] = row_counts.get(r, 0) + 1
        col_counts[c] = col_counts.get(c, 0) + 1

    # Find spines (rows/cols with 2+ points)
    spine_rows = sorted([r for r, c in row_counts.items() if c >= 2])
    spine_cols = sorted([c for c, r in col_counts.items() if r >= 2])

    out = np.zeros((height, width), dtype=int)
    for r, c in pairs:
        out[r, c] = 2

    # Fill spines
    for r in spine_rows:
        cols_on_row = [c for rc,c_ in pairs if rc == r]
        min_c, max_c = min(cols_on_row), max(cols_on_row)
        for c in range(min_c, max_c + 1):
            if not ((r, c) in pairs):
                out[r, c] = 3

    for c in spine_cols:
        rows_on_col = [r for r,rc in pairs if rc == c]
        min_r, max_r = min(rows_on_col), max(rows_on_col)
        for r in range(min_r, max_r + 1):
            if not ((r, c) in pairs):
                out[r, c] = 3

    # Connect isolated points to nearest spine
    # Priority: connect via shortest Manhattan path that stays within bounds
    # For each isolated point, find nearest spine member and connect perpendicularly

    isolated_points = [(r,c) for r,c in pairs 
                       if sum(1 for rc,cc in pairs if rc == r or cc == c) <= 1]
    print(f"Isolated points: {isolated_points}")

    # Sort by distance to any spine
    def dist_to_spine(pt):
        r, c = pt
        min_dist = float('inf')
        for sr in spine_rows:
            d = abs(r - sr)
            if d < min_dist:
                min_dist = d
        for sc in spine_cols:
            d = abs(c - sc)
            if d < min_dist:
                min_dist = d
        return min_dist, min_dist

    isolated_points.sort(key=lambda p: dist_to_spine(p)[0])

    for pt in isolated_points:
        r, c = pt

        # Find closest spine row
        closest_row = min(spine_rows, key=lambda sr: abs(r - sr))
        closest_col = min(spine_cols, key=lambda sc: abs(c - sc)) if spine_cols else None

        # If there's a spine row, connect vertically
        if closest_row is not None:
            start_r, end_r = min(r, closest_row), max(r, closest_row)
            for rr in range(start_r, end_r + 1):
                if (rr, c) not in pairs:
                    out[rr, c] = 3
        # If there's a spine column but no row, connect horizontally
        elif closest_col is not None:
            start_c, end_c = min(c, closest_col), max(c, closest_col)
            for cc in range(start_c, end_c + 1):
                if (r, cc) not in pairs:
                    out[r, cc] = 3

    return out

